From 0e882cc4944bdd6305cafd5d2c05a063c7f873d7 Mon Sep 17 00:00:00 2001
From: tomas-muller <muller@unitime.org>
Date: Mon, 26 Oct 2015 17:01:34 +0100
Subject: [PATCH] iCalendar Exports

- ensure that the exported dates are in the local timezone
- this fixes the issue with daylight savings that was introduced in commit 592152d
  (Biweekly 0.4.3 defaults to UTC dates)

diff --git a/JavaSource/org/unitime/timetable/events/EventEmail.java b/JavaSource/org/unitime/timetable/events/EventEmail.java
index f434dcecc..fb40c2f1e 100644
--- a/JavaSource/org/unitime/timetable/events/EventEmail.java
+++ b/JavaSource/org/unitime/timetable/events/EventEmail.java
@@ -68,9 +68,9 @@ import org.unitime.timetable.security.rights.Right;
 import org.unitime.timetable.util.Constants;
 import org.unitime.timetable.util.NameFormat;

-import biweekly.Biweekly;
 import biweekly.ICalVersion;
 import biweekly.ICalendar;
+import biweekly.io.text.ICalWriter;
 import biweekly.property.CalendarScale;
 import biweekly.property.Method;
 import biweekly.property.Status;
@@ -340,8 +340,21 @@ public class EventEmail {
         		ical,
         		response().hasEventWithId() && response().getEvent().hasMeetings() ? response().getEvent() : request().getEvent(),
         		response().hasEventWithId() && response().getEvent().hasMeetings() ? null : Status.cancelled());
-
-		return (exp ? Biweekly.write(ical).go() : null);		
+        
+        if (exp) {
+        	StringWriter ret = new StringWriter();
+	        ICalWriter writer = new ICalWriter(ret, ICalVersion.V2_0);
+	    	writer.getTimezoneInfo().setDefaultTimeZone(TimeZone.getDefault());
+	        try {
+	        	writer.write(ical);
+	        	writer.flush();
+	        } finally {
+	        	writer.close();
+	        }
+	        return ret.toString();
+        } else {
+        	return null;
+        }
 	}

 	public static void eventExpired(Event cancelledEvent, Set<Meeting> cancelledMeetings) throws Exception {

diff --git a/JavaSource/org/unitime/timetable/gwt/server/CalendarServlet.java b/JavaSource/org/unitime/timetable/gwt/server/CalendarServlet.java
index 16f51aeee..f8a20c3cb 100644
--- a/JavaSource/org/unitime/timetable/gwt/server/CalendarServlet.java
+++ b/JavaSource/org/unitime/timetable/gwt/server/CalendarServlet.java
@@ -83,11 +83,11 @@ import org.unitime.timetable.solver.service.SolverServerService;
 import org.unitime.timetable.util.Constants;
 import org.unitime.timetable.util.DateUtils;

-import biweekly.Biweekly;
 import biweekly.ICalVersion;
 import biweekly.ICalendar;
 import biweekly.component.VEvent;
 import biweekly.component.VFreeBusy;
+import biweekly.io.text.ICalWriter;
 import biweekly.parameter.Role;
 import biweekly.property.Attendee;
 import biweekly.property.CalendarScale;
@@ -273,11 +273,15 @@ public class CalendarServlet extends HttpServlet {
         }

 		PrintWriter out = response.getWriter();
+        ICalWriter writer = new ICalWriter(out, ICalVersion.V2_0);
 		try {
-            Biweekly.write(ical).go(out);
+	    	writer.getTimezoneInfo().setDefaultTimeZone(TimeZone.getDefault());
+        	writer.write(ical);
+        	writer.flush();
         	out.flush();
 		} finally {
 			out.close();
+			writer.close();
 		}
 	}


diff --git a/JavaSource/org/unitime/timetable/export/events/EventsExportEventsToICal.java b/JavaSource/org/unitime/timetable/export/events/EventsExportEventsToICal.java
index 4bc4bc960..df580ea9e 100644
--- a/JavaSource/org/unitime/timetable/export/events/EventsExportEventsToICal.java
+++ b/JavaSource/org/unitime/timetable/export/events/EventsExportEventsToICal.java
@@ -59,10 +59,10 @@ import org.unitime.timetable.model.dao.SubjectAreaDAO;
 import org.unitime.timetable.model.dao._RootDAO;
 import org.unitime.timetable.util.Constants;

-import biweekly.Biweekly;
 import biweekly.ICalVersion;
 import biweekly.ICalendar;
 import biweekly.component.VEvent;
+import biweekly.io.text.ICalWriter;
 import biweekly.parameter.Role;
 import biweekly.property.Attendee;
 import biweekly.property.CalendarScale;
@@ -104,7 +104,14 @@ public class EventsExportEventsToICal extends EventsExporter {
         for (EventInterface event: events)
 			print(ical, event);

-        Biweekly.write(ical).go(helper.getWriter());
+        ICalWriter writer = new ICalWriter(helper.getWriter(), ICalVersion.V2_0);
+    	writer.getTimezoneInfo().setDefaultTimeZone(TimeZone.getDefault());
+        try {
+        	writer.write(ical);
+        	writer.flush();
+        } finally {
+        	writer.close();
+        }
 	}

 	public boolean print(ICalendar ical, EventInterface event) throws IOException {

diff --git a/JavaSource/org/unitime/timetable/onlinesectioning/updates/CalendarExport.java b/JavaSource/org/unitime/timetable/onlinesectioning/updates/CalendarExport.java
index 09b48f9a7..ce3fd0a55 100644
--- a/JavaSource/org/unitime/timetable/onlinesectioning/updates/CalendarExport.java
+++ b/JavaSource/org/unitime/timetable/onlinesectioning/updates/CalendarExport.java
@@ -20,6 +20,7 @@
 package org.unitime.timetable.onlinesectioning.updates;

 import java.io.IOException;
+import java.io.StringWriter;
 import java.net.URL;
 import java.util.BitSet;
 import java.util.Calendar;
@@ -47,11 +48,11 @@ import org.unitime.timetable.onlinesectioning.model.XTime;
 import org.unitime.timetable.server.CourseDetailsBackend;
 import org.unitime.timetable.util.Constants;

-import biweekly.Biweekly;
 import biweekly.ICalVersion;
 import biweekly.ICalendar;
 import biweekly.component.VEvent;
 import biweekly.component.VFreeBusy;
+import biweekly.io.text.ICalWriter;
 import biweekly.parameter.Role;
 import biweekly.property.Attendee;
 import biweekly.property.CalendarScale;
@@ -112,7 +113,16 @@ public class CalendarExport implements OnlineSectioningAction<String>{
         		}
         	}

-			return Biweekly.write(ical).go();
+			StringWriter ret = new StringWriter();
+	        ICalWriter writer = new ICalWriter(ret, ICalVersion.V2_0);
+	    	writer.getTimezoneInfo().setDefaultTimeZone(TimeZone.getDefault());
+	        try {
+	        	writer.write(ical);
+	        	writer.flush();
+	        } finally {
+	        	writer.close();
+	        }
+	        return ret.toString();
 		} catch (IOException e) {
 			throw new SectioningException(e.getMessage(), e);
 		}
@@ -144,8 +154,18 @@ public class CalendarExport implements OnlineSectioningAction<String>{
 						DayCode.toString(ft.getTime().getDays()), ft.getTime().getSlot(), ft.getTime().getLength(), ical);
 			}
 		}
+		
+		StringWriter ret = new StringWriter();
+        ICalWriter writer = new ICalWriter(ret, ICalVersion.V2_0);
+    	writer.getTimezoneInfo().setDefaultTimeZone(TimeZone.getDefault());
+        try {
+        	writer.write(ical);
+        	writer.flush();
+        } finally {
+        	writer.close();
+        }

-		return Biweekly.write(ical).go();		
+        return ret.toString();		
 	}

 	private static void printSection(OnlineSectioningServer server, XCourse course, XSection section, ICalendar ical) throws IOException {
